typedef struct node {
 double mean;
 double count;
} node_t;

struct td_histogram {
 double compression;
 int cap;
 int merged_nodes;
 int unmerged_nodes;
 double merged_count;
 double unmerged_count;
 node_t nodes[0];
};
У каждого центроида два поля: среднее значение (
mean
) и вес (
count
). Гистограмма хранит два массива центроидов в одном буфере: сначала «слитые» (
merged_nodes
), затем «буферные» (
unmerged_nodes
). Это позволяет добавлять точки без пересортировки всего массива. Поле
nodes[0]
— гибкий массив (flexible array member), память под него выделяется сразу в
td_new
.
❯ Основные функции
Создание и удаление:
td_histogram_t* td_new(double compression) {
 size_t memsize = td_required_buf_size(compression);
 return td_init(compression, memsize, (char*)(malloc(memsize)));
}
Ёмкость вычисляется как
6 * compression + 10
. Коэффициент 6 взят с запасом — экспериментально подтверждено, что число центроидов не превышает
compression
.
Добавление точки:
void td_add(td_histogram_t* h, double mean, double count) {
 if (should_merge(h)) {
 merge(h);
 }
 h->nodes[next_node(h)] = (node_t){.mean = mean, .count = count};
 h->unmerged_nodes++;
 h->unmerged_count += count;
}
Точка всегда попадает в буфер. Когда
merged_nodes + unmerged_nodes == cap
, вызывается
merge()
.
Слияние (ядро алгоритма):
static void merge(td_histogram_t* h) {
 if (h->unmerged_nodes == 0) return;
 int N = h->merged_nodes + h->unmerged_nodes;
 qsort(h->nodes, N, sizeof(node_t), &compare_nodes);

 double total_count = h->merged_count + h->unmerged_count;
 double denom = 2 * M_PI * total_count * log(total_count);
 double normalizer = h->compression / denom;

 int cur = 0;
 double count_so_far = 0;
 for (int i = 1; i < N; i++) {
 double proposed_count = h->nodes[cur].count + h->nodes[i].count;
 double z = proposed_count * normalizer;
 double q0 = count_so_far / total_count;
 double q2 = (count_so_far + proposed_count) / total_count;
 bool should_add = (z <= (q0 * (1 - q0))) && (z <= (q2 * (1 - q2)));
 if (should_add) {
 h->nodes[cur].count += h->nodes[i].count;
 double delta = h->nodes[i].mean - h->nodes[cur].mean;
 double weighted_delta = (delta * h->nodes[i].count) / h->nodes[cur].count;
 h->nodes[cur].mean += weighted_delta;
 } else {
 count_so_far += h->nodes[cur].count;
 cur++;
 h->nodes[cur] = h->nodes[i];
 }
 }
 h->merged_nodes = cur + 1;
 h->merged_count = total_count;
 h->unmerged_nodes = 0;
 h->unmerged_count = 0;
}
Здесь видно что все центроиды (и старые, и новые из буфера) сортируются по
mean
. Затем вычисляется эвристический нормализатор (он используется в этой реализации, можно было бы использовать более сложный на основе арксинуса, но на практике в 99% случаев подходит и наш упрощенный вариант)
normalizer = compression / (2π · total_count · log(total_count))
. Затем для каждого центроида высчитывается
z = proposed_count · normalizer
, и если он не превышает
q0(1-q0)
и
q2(1-q2)
, центроиды склеиваются. Ну и при склеивании вес суммируется, среднее пересчитывается как взвешенное.
В коде используется эмпирический нормализатор с
log(total_count)
вместо оригинальной scale function с арксинусом. Арксинус точнее на хвостах, но чуть медленнее и менее точен в остальном. Для практических задач упрощенной реализации хватит с головой.
Реализация с arcsin
Если вы хотите использовать ее, можете заменить функцию merge на эту:
static void merge(td_histogram_t* h) {
 if (h->unmerged_nodes == 0) {
 return;
 }
 int N = h->merged_nodes + h->unmerged_nodes;
 qsort((void*)(h->nodes), N, sizeof(node_t), &compare_nodes);

 double total_count = h->merged_count + h->unmerged_count;

 int cur = 0;
 double count_so_far = 0;

 for (int i = 1; i < N; i++) {
 double proposed_count = h->nodes[cur].count + h->nodes[i].count;

 double q_left = count_so_far / total_count;
 double q_right = (count_so_far + proposed_count) / total_count;

 double k_left = (h->compression / (2 * M_PI)) * asin(2 * q_left - 1);
 double k_right = (h->compression / (2 * M_PI)) * asin(2 * q_right - 1);

 bool should_add = (k_right - k_left) <= 1.0;

 if (should_add) {
 h->nodes[cur].count += h->nodes[i].count;
 double delta = h->nodes[i].mean - h->nodes[cur].mean;
 double weighted_delta = (delta * h->nodes[i].count) / h->nodes[cur].count;
 h->nodes[cur].mean += weighted_delta;
 } else {
 count_so_far += h->nodes[cur].count;
 cur++;
 h->nodes[cur] = h->nodes[i];
 }
 }

 h->merged_nodes = cur + 1;
 h->merged_count = total_count;
 h->unmerged_nodes = 0;
 h->unmerged_count = 0;
}
